INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (101, 'Apex Phoenix', 1001, 1004, 4, 1, 1, 'The dream team of Doragon's top two faces. Ryūga the Apex and Suzaku the Phoenix — the ace and the charismatic star. When they team up, the crowd goes wild.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (102, 'Iron Fist Cobra', 1002, 1007, 4, 1, 1, 'The veteran heel tag team. Kuroda the Iron Fist and The Honma Cobra — a brutal striker and a cocky submission specialist. A nightmare for any face team.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (103, 'Riverstone Striker', 1005, 1006, 4, 1, 1, 'The technical powerhouse team. Tatsuya Riverstone and Shibata the Striker — a technical specialist and a hard-hitting fighter. Complementary styles.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (104, 'Thunder Shadow', 1010, 1011, 4, 1, 1, 'The midcard heel-killer duo. Thunder Suzuki (face) and Shadow Endo (heel) — rivals who occasionally team up against common enemies. Tension guaranteed.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (105, 'Ueno Nakajima Connection', 1016, 1018, 4, 2, 1, 'The ace team of Fenikkusu. Yuya Ueno and Asahi Nakajima — the B-brand's top faces. A high-flying, technically sound duo.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (106, 'Storm Iron', 1019, 1020, 4, 2, 1, 'The gatekeeper team. Storm Nishimura (face) and Iron Fukuda (heel) — rivals who team up when they need to. A volatile but effective pairing.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (107, 'Young Lions United', 1024, 1026, 4, 2, 1, 'The developmental team. Kaito Abe and Daiki Ikeda — two young lions learning the ropes as a tag team. The future of Fenikkusu's tag division.');
INSERT INTO tagteams (tagteamID, tagteamName, worker1, worker2, promotionID, brandID, isActive, description) VALUES (108, 'Monster Squad', 1027, 1022, 4, 2, 1, 'The chaos team. Wolf Hashimoto and Savage Fujita — two wild heels who destroy everything in their path. Terrifying but uncontrollable.');
INSERT INTO stables (stableID, stableName, promotionID, brandID, leaderWorkerID, description, isActive) VALUES (201, 'The Iron Court', 4, 1, 1002, 'A heel stable led by Kuroda the Iron Fist. The court includes The Honma Cobra (1007), Absolute Ryo (1008), Shadow Endo (1011), and Silent Goto (1014). The dominant heel faction of Doragon, they control the main event scene through fear and intimidation. Their motto: 'Bow or be broken.'', 1);
