INSERT INTO stables (stableID, stableName, promotionID, brandID, leaderWorkerID, description, isActive) VALUES (202, 'The Phoenix Academy', 4, 2, 1004, 'A face stable led by Suzaku the Phoenix. The academy includes Zen Takahashi (1013), Kohei Hase (1015), and Asahi Nakajima (1018, on loan from Fenikkusu). A mentoring stable where the ace trains the next generation. Their motto: 'Rise from the ashes.'', 1);
