INSERT INTO stables (stableID, stableName, promotionID, brandID, leaderWorkerID, description, isActive) VALUES (203, 'The Fenikkusu Vanguard', 4, 2, 1016, 'A face stable on the B-brand led by Yuya Ueno. The vanguard includes Storm Nishimura (1019), Sora Maeda (1021), and Ren Okada (1023). A group of young lions fighting for call-ups to Doragon. Their motto: 'The phoenix rises through fire.'', 1);
