INSERT INTO stables (stableID, stableName, promotionID, brandID, leaderWorkerID, description, isActive) VALUES (204, 'The Monster Pack', 4, 2, 1027, 'A heel stable on Fenikkusu led by Wolf Hashimoto. The pack includes Savage Fujita (1022), Blade Mori (1025), and Satoshi Sakurai (1030). A group of monsters and brawlers who terrorize the B-brand. Their motto: 'We are the nightmare.'', 1);
